import { providerApiKeyEnvironment, providerDisplayName, } from "../providers.js";
export const missingConfigurationMessage = (configPath) => `Jevvy cannot start because no provider is configured. Run "npx @jevvy/permissions init", or create ${configPath} manually. OpenCode's remaining permission flow remains unchanged.`;
export const invalidConfigurationMessage = (configPath, detail) => `Jevvy cannot start because ${configPath} is invalid: ${detail}. Fix the file before enabling auto-approval. OpenCode's remaining permission flow remains unchanged.`;
export const missingCredentialMessage = (provider, configPath) => `${providerDisplayName(provider)} has no credential. Set ${providerApiKeyEnvironment(provider)}, add providers.${provider}.apiKey to ${configPath}, or run "npx @jevvy/permissions init". OpenCode's remaining permission flow remains unchanged.`;
export const missingOpenCodeCredentialMessage = (provider, integrationID, configPath) => `${providerDisplayName(provider)} has no credential. Jevvy could not read a key from the "${integrationID}" integration in OpenCode. Connect that integration, or add providers.${provider}.apiKey to ${configPath}, or set ${providerApiKeyEnvironment(provider)}. OpenCode's remaining permission flow remains unchanged.`;
